internal val COUNTRY_NAMES_HY: String =
    "root\u001F01Անդորրա\u001EԱրաբական Միացյալ Էմիրություններ\u001EԱֆղանստան\u001EԱնտիգուա և Բարբուդա\u001EԱնգուիլա\u001EԱլբանիա\u001EՀայաստան\u001EԱնգոլա\u001EԱնտարկտիդա\u001EԱրգենտինա\u001EԱմերիկյան Սամոա\u001EԱվստրիա\u001EԱվստրալիա\u001EԱրուբա\u001EԱլանդյան կղզիներ\u001EԱդրբեջան\u001EԲոսնիա և Հերցեգովինա\u001EԲարբադոս\u001EԲանգլադեշ\u001EԲելգիա\u001EԲուրկինա Ֆասո\u001EԲուլղարիա\u001EԲահրեյն\u001EԲուրունդի\u001EԲենին\u001EՍուրբ Բարդուղիմեոս\u001EԲերմուդներ\u001EԲրունեյ\u001EԲոլիվիա\u001EԿարիբյան Նիդեռլանդներ\u001EԲրազիլիա\u001EԲահամյան կղզիներ\u001EԲութան\u001EԲուվե կղզի\u001EԲոտսվանա\u001EԲելառուս\u001EԲելիզ\u001EԿանադա\u001EԿոկոսյան (Քիլինգ) կղզիներ\u001EԿոնգո - Կինշասա\u001EԿենտրոնական Աֆրիկյան Հանրապետություն\u001EԿոնգո - Բրազավիլ\u001EՇվեյցարիա\u001EԿոտ դ՚Իվուար\u001EԿուկի կղզիներ\u001EՉիլի\u001EԿամերուն\u001EՉինաստան\u001EԿոլումբիա\u001EԿոստա Ռիկա\u001EԿուբա\u001EԿաբո Վերդե\u001EԿյուրասաո\u001EՍուրբ Ծննդյան կղզի\u001EԿիպրոս\u001EՉեխիա\u001EԳերմանիա\u001EՋիբութի\u001EԴանիա\u001EԴոմինիկա\u001EԴոմինիկյան Հանրապետություն\u001EԱլժիր\u001EԷկվադոր\u001EԷստոնիա\u001EԵգիպտոս\u001EԱրևմտյան Սահարա\u001EԷրիթրեա\u001EԻսպանիա\u001EԵթովպիա\u001EՖինլանդիա\u001EՖիջի\u001EՖոլքլենդյան կղզիներ\u001EՄիկրոնեզիա\u001EՖարերյան կղզիներ\u001EՖրանսիա\u001EԳաբոն\u001EՄիացյալ Թագավորություն\u001EԳրենադա\u001EՎրաստան\u001EՖրանսիական Գվիանա\u001EԳերնսի\u001EԳանա\u001EՋիբրալթար\u001EԳրենլանդիա\u001EԳամբիա\u001EԳվինեա\u001EԳվադելուպա\u001EՀասարակածային Գվինեա\u001EՀունաստան\u001EՀարավային Ջորջիա և Հարավային Սենդվիչյան կղզիներ\u001EԳվատեմալա\u001EԳուամ\u001EԳվինեա-Բիսաու\u001EԳայանա\u001EՀոնկոնգի ՀՎՇ\u001EՀերդ կղզի և ՄակԴոնալդի կղզիներ\u001EՀոնդուրաս\u001EԽորվաթիա\u001EՀայիթի\u001EՀունգարիա\u001EԻնդոնեզիա\u001EԻռլանդիա\u001EԻսրայել\u001EՄեն կղզի\u001EՀնդկաստան\u001EԲրիտանական տարածք Հնդկական Օվկիանոսում\u001EԻրաք\u001EԻրան\u001EԻսլանդիա\u001EԻտալիա\u001EՋերսի\u001EՃամայկա\u001EՀորդանան\u001EՃապոնիա\u001EՔենիա\u001EՂրղզստան\u001EԿամբոջա\u001EԿիրիբատի\u001EԿոմորյան կղզիներ\u001EՍենթ Քիտս և Նևիս\u001EՀյուսիսային Կորեա\u001EՀարավային Կորեա\u001EՔուվեյթ\u001EԿայմանյան կղզիներ\u001EՂազախստան\u001EԼաոս\u001EԼիբանան\u001EՍենթ Լյուսիա\u001EԼիխտենշտեյն\u001EՇրի Լանկա\u001EԼիբերիա\u001EԼեսոտո\u001EԼիտվա\u001EԼյուքսեմբուրգ\u001EԼատվիա\u001EԼիբիա\u001EՄարոկկո\u001EՄոնակո\u001EՄոլդովա\u001EՉեռնոգորիա\u001EՍեն Մարտեն\u001EՄադագասկար\u001EՄարշալյան կղզիներ\u001EՀյուսիսային Մակեդոնիա\u001EՄալի\u001EՄյանմա (Բիրմա)\u001EՄոնղոլիա\u001EՉինաստանի Մակաո ՀՎՇ\u001EՀյուսիսային Մարիանյան կղզիներ\u001EՄարտինիկա\u001EՄավրիտանիա\u001EՄոնսեռատ\u001EՄալթա\u001EՄավրիկիոս\u001EՄալդիվներ\u001EՄալավի\u001EՄեքսիկա\u001EՄալայզիա\u001EՄոզամբիկ\u001EՆամիբիա\u001EՆոր Կալեդոնիա\u001EՆիգեր\u001EՆորֆոլկ կղզի\u001EՆիգերիա\u001EՆիկարագուա\u001EՆիդեռլանդներ\u001EՆորվեգիա\u001EՆեպալ\u001EՆաուրու\u001EՆիուե\u001EՆոր Զելանդիա\u001EՕման\u001EՊանամա\u001EՊերու\u001EՖրանսիական Պոլինեզիա\u001EՊապուա Նոր Գվինեա\u001EՖիլիպիններ\u001EՊակիստան\u001EԼեհաստան\u001EՍեն Պիեռ և Միքելոն\u001EՊիտկեռն կղզիներ\u001EՊուերտո Ռիկո\u001EՊաղեստինյան տարածքներ\u001EՊորտուգալիա\u001EՊալաու\u001EՊարագվայ\u001EԿատար\u001EՌեյունիոն\u001EՌումինիա\u001EՍերբիա\u001EՌուսաստան\u001EՌուանդա\u001EՍաուդյան Արաբիա\u001EՍողոմոնյան կղզիներ\u001EՍեյշելներ\u001EՍուդան\u001EՇվեդիա\u001EՍինգապուր\u001EՍուրբ Հեղինեի կղզի\u001EՍլովենիա\u001EՍվալբարդ և Յան Մայեն\u001EՍլովակիա\u001EՍիեռա Լեոնե\u001EՍան Մարինո\u001EՍենեգալ\u001EՍոմալի\u001EՍուրինամ\u001EՀարավային Սուդան\u001EՍան Տոմե և Փրինսիպի\u001EՍալվադոր\u001EՍինտ Մարտեն\u001EՍիրիա\u001EԷսվատինի\u001EԹըրքս և Կայկոս կղզիներ\u001EՉադ\u001EՖրանսիական Հարավային Տարածքներ\u001EՏոգո\u001EԹաիլանդ\u001EՏաջիկստան\u001EՏոկելաու\u001EԹիմոր Լեշտի\u001EԹուրքմենստան\u001EԹունիս\u001EՏոնգա\u001EԹուրքիա\u001EՏրինիդադ և Տոբագո\u001EՏուվալու\u001EԹայվան\u001EՏանզանիա\u001EՈւկրաինա\u001EՈւգանդա\u001EԱրտաքին կղզիներ (ԱՄՆ)\u001EՄիացյալ Նահանգներ\u001EՈւրուգվայ\u001EՈւզբեկստան\u001EՎատիկան\u001EՍենթ Վինսենթ և Գրենադիններ\u001EՎենեսուելա\u001EԲրիտանական Վիրջինյան կղզիներ\u001EԱՄՆ Վիրջինյան կղզիներ\u001EՎիետնամ\u001EՎանուատու\u001EՈւոլիս և Ֆուտունա\u001EՍամոա\u001EԵմեն\u001EՄայոտ\u001EՀարավաֆրիկյան Հանրապետություն\u001EԶամբիա\u001EԶիմբաբվե"

internal val COUNTRY_NAMES_HY_AM: String =
    "hy\u001F00"
